style.css:
@-moz-document domain("roblox.com") {
body {
        background: url("https://i.ytimg.com/vi/LgerkG22CCU/maxresdefault.jpg?sqp=-oaymwEmCIAKENAF8quKqQMa8AEB-AH-CYAC0AWKAgwIABABGGUgXygxMA8=&amp;rs=AOn4CLCG-J_Gg0QMU7xwqHPJ-oGGbl-BNw") no-repeat center center fixed !important;
        background-size: cover !important;
    }

   
    .content, .container, .card, .section, .navbar, .header, #navigation {
        background: transparent !important;
    }

    a {
        color: #ff3b3b !important;
    }

    button, .btn-primary, .btn-common {
        background-color: #ff3b3b !important;
        color: #fff !important;
        border-radius: 6px !important;
        border: none !important;
    }

    button:hover, .btn-primary:hover, .btn-common:hover {
        background-color: #cc0000 !important;
    }
}
